/** `text`'s words in `lang` from this table, or null. */
export const screenWord = (text, lang) => {
    const i = ORDER.indexOf(lang);
    return i === -1 ? null : SCREENS[text]?.[i] || null;
};
/** A text with its {0}, {1}… filled: fill('Next up: {0}', title). */
export const fill = (text, ...args) => String(text).replace(/\{(\d)\}/g, (_, k) => String(args[Number(k)] ?? ''));

/*
 * "Write “ಬೆಕ್ಕು” in English" (2026-11-06, the user's Duolingo picture), in each student's language: the word to write,
 * and in which language — "in English" as each language says it, else that language by its name ("in Japanese").
 */
const IN_ENGLISH = {
    en: 'in English', kn: 'ಇಂಗ್ಲಿಷ್‌ನಲ್ಲಿ', hi: 'अंग्रेज़ी में', ta: 'ஆங்கிலத்தில்', te: 'ఇంగ్లీష్‌లో', ml: 'ഇംഗ്ലീഷിൽ', mr: 'इंग्रजीत', bn: 'ইংরেজিতে',
    gu: 'અંગ્રેજીમાં', pa: 'ਅੰਗਰੇਜ਼ੀ ਵਿੱਚ', or: 'ଇଂରାଜୀରେ', ur: 'انگریزی میں', es: 'en inglés', fr: 'en anglais', de: 'auf Englisch', pt: 'em inglês',
    ru: 'по-английски', ar: 'بالإنجليزية', zh: '用英语', ja: '英語で', ko: '영어로'
};
const IN_LANGUAGE = {
    en: (n) => `in ${n}`, kn: (n) => `${n} ಭಾಷೆಯಲ್ಲಿ`, hi: (n) => `${n} भाषा में`, ta: (n) => `${n} மொழியில்`, te: (n) => `${n} భాషలో`, ml: (n) => `${n} ഭാഷയിൽ`,
    mr: (n) => `${n} भाषेत`, bn: (n) => `${n} ভাষায়`, gu: (n) => `${n} ભાષામાં`, pa: (n) => `${n} ਭਾਸ਼ਾ ਵਿੱਚ`, or: (n) => `${n} ଭାଷାରେ`, ur: (n) => `${n} زبان میں`,
    es: (n) => `en ${n}`, fr: (n) => `en ${n}`, de: (n) => `auf ${n}`, pt: (n) => `em ${n}`, ru: (n) => `на языке ${n}`, ar: (n) => `باللغة ${n}`,
    zh: (n) => `用${n}`, ja: (n) => `${n}で`, ko: (n) => `${n}로`
};
const WRITE_WORD = {
    en: (w, i) => `Write “${w}” ${i}`, kn: (w, i) => `“${w}” ಅನ್ನು ${i} ಬರೆಯಿರಿ`, hi: (w, i) => `“${w}” को ${i} लिखें`, ta: (w, i) => `“${w}” என்பதை ${i} எழுதுங்கள்`,
    te: (w, i) => `“${w}” ను ${i} రాయండి`, ml: (w, i) => `“${w}” ${i} എഴുതുക`, mr: (w, i) => `“${w}” ${i} लिहा`, bn: (w, i) => `“${w}” ${i} লিখুন`,
    gu: (w, i) => `“${w}” ને ${i} લખો`, pa: (w, i) => `“${w}” ਨੂੰ ${i} ਲਿਖੋ`, or: (w, i) => `“${w}” କୁ ${i} ଲେଖ`, ur: (w, i) => `“${w}” کو ${i} لکھیں`,
    es: (w, i) => `Escribe “${w}” ${i}`, fr: (w, i) => `Écris « ${w} » ${i}`, de: (w, i) => `Schreib „${w}“ ${i}`, pt: (w, i) => `Escreva “${w}” ${i}`,
    ru: (w, i) => `Напишите «${w}» ${i}`, ar: (w, i) => `اكتب «${w}» ${i}`, zh: (w, i) => `${i}写出“${w}”`, ja: (w, i) => `「${w}」を${i}書こう`, ko: (w, i) => `“${w}”을(를) ${i} 쓰세요`
};
/** The title "Write “word” in English" in the student's language `lang`; `name` the language to write in, as the student calls it. */
export const writeWordTitle = (lang, word, target, name) => {
    const say = WRITE_WORD[lang] || WRITE_WORD.en;
    const inIt = target === 'en' ? (IN_ENGLISH[lang] || IN_ENGLISH.en) : (IN_LANGUAGE[lang] || IN_LANGUAGE.en)(name);
    return say(word, inIt);
};
